package utahfs

import (
	"testing"

	"bytes"
	"context"
	crand "crypto/rand"
	"io"
	"math/rand"
	"time"

	"github.com/cloudflare/utahfs/persistent"
)

func init() {
	rand.Seed(time.Now().UnixNano())
}

type testData struct {
	bf   *BlockFile
	pos  int
	data []byte
}

func testBFS(t *testing.T, td *testData) {
	bf, pos, data := td.bf, td.pos, td.data

	dice := rand.Intn(30)

	if len(data) > 0 && dice == 0 { // Seek from start.
		off := rand.Int63n(int64(len(data)))
		got, err := bf.Seek(off, io.SeekStart)
		if err != nil {
			t.Fatal(err)
		}
		pos = int(off)
		if got != int64(pos) {
			t.Fatalf("%v != %v", got, pos)
		}
	} else if len(data) > 0 && pos != len(data) && dice == 1 { // Seek from current.
		off := rand.Int63n(int64(len(data) - pos))
		got, err := bf.Seek(off, io.SeekCurrent)
		if err != nil {
			t.Fatal(err)
		}
		pos += int(off)
		if got != int64(pos) {
			t.Fatalf("%v != %v", got, pos)
		}
	} else if len(data) > 0 && dice == 2 { // Seek from end.
		off := rand.Int63n(int64(len(data)))
		got, err := bf.Seek(-off, io.SeekEnd)
		if err != nil {
			t.Fatal(err)
		}
		pos = len(data) - int(off)
		if got != int64(pos) {
			t.Fatalf("%v != %v", got, pos)
		}
	} else if len(data) > 0 && dice == 3 { // Truncate.
		size := rand.Int63n(int64(len(data)))
		err := bf.Truncate(size)
		if err != nil {
			t.Fatal(err)
		}
		pos = int(size)
		data = data[:size]
	} else if len(data) > 0 && dice < 20 { // Read.
		p := make([]byte, rand.Int63n(256)+1)

		n, err := bf.Read(p)
		if pos == len(data) {
			if err != io.EOF {
				t.Fatal("expected EOF when reading at end of file")
			} else if n != 0 {
				t.Fatal("read past end of file")
			}
		} else if pos != len(data) {
			if err != nil {
				t.Fatal(err)
			} else if n == 0 {
				t.Fatal("read zero bytes even though there was data")
			}
		}
		if n > len(p) || pos+n > len(data) {
			t.Fatalf("%v violates bounds", n)
		} else if !bytes.Equal(data[pos:pos+n], p[:n]) {
			t.Fatal("read unexpected data")
		}
		pos += n
	} else { // Write.
		p := make([]byte, rand.Int63n(3*256)+1)
		crand.Read(p)

		n, err := bf.Write(p)
		if err != nil {
			t.Fatal(err)
		} else if n != len(p) {
			t.Fatalf("%v != %v", n, len(p))
		}

		if pos+n > len(data) {
			data = append(data[:pos], p...)
		} else {
			copy(data[pos:pos+n], p)
		}
		pos += n
	}

	td.pos, td.data = pos, data
}

func TestBlockFilesystemSplitPtrs(t *testing.T) {
	testBlockFilesystem(t, true)
}

func TestBlockFilesystem(t *testing.T) {
	testBlockFilesystem(t, false)
}

func testBlockFilesystem(t *testing.T, splitPtrs bool) {
	ctx := context.Background()

	store := persistent.NewAppStorage(persistent.NewBlockMemory())
	if err := store.Start(ctx); err != nil {
		t.Fatal(err)
	}
	bfs, err := NewBlockFilesystem(store, 3, 256, splitPtrs)
	if err != nil {
		t.Fatal(err)
	}

	ptrs := make([]uint64, 0)
	files := make(map[uint64]*testData)

	for i := 0; i < 100000; i++ {
		dice := rand.Intn(10000)

		if len(ptrs) == 0 || dice == 0 {
			ptr, bf, err := bfs.Create(ctx, persistent.Content)
			if err != nil {
				t.Fatal(err)
			}
			ptrs = append(ptrs, ptr)
			files[ptr] = &testData{bf, 0, nil}
		} else {
			ptr := ptrs[rand.Intn(len(ptrs))]
			testBFS(t, files[ptr])
		}
	}

	t.Logf("created %v files", len(ptrs))
	sum := 0
	for _, ptr := range ptrs {
		n := len(files[ptr].data)
		sum += n
		t.Logf("- %x: contains %v bytes", ptr, n)
	}
	t.Logf("%v bytes total", sum)
}

package persistent

import (
	"testing"
)

func TestParentStep(t *testing.T) {
	checkParents := func(node uint64, parents ...uint64) {
		for _, parent := range parents {
			node = parentStep(node)
			if node != parent {
				t.Fatalf("unexpected parent node returned: got=%v, expected=%v", node, parent)
			}
		}
	}

	checkParents(0, 1, 3, 7)
	checkParents(2, 1, 3, 7)
	checkParents(4, 5, 3, 7)
	checkParents(6, 5, 3, 7)
	checkParents(8, 9, 11, 7)
	checkParents(10, 9, 11, 7)
	checkParents(12, 13, 11, 7)
}

func TestRootNode(t *testing.T) {
	checkRoot := func(leaves, expected uint64) {
		if cand := rootNode(leaves); cand != expected {
			t.Fatalf("unexpected root node returned: got=%v, expected=%v", cand, expected)
		}
	}

	checkRoot(2, 1)
	checkRoot(10, 15)
	checkRoot(7, 7)
}

package persistent

import (
	"context"
)

type blockMemory map[uint64][]byte

// NewBlockMemory returns an implementation of BlockStorage that simply stores
// data in-memory.
func NewBlockMemory() BlockStorage { return make(blockMemory) }

func (bm blockMemory) Start(ctx context.Context, prefetch []uint64) (map[uint64][]byte, error) {
	return bm.GetMany(ctx, prefetch)
}

func (bm blockMemory) Get(ctx context.Context, ptr uint64) ([]byte, error) {
	d, ok := bm[ptr]
	if !ok {
		return nil, ErrObjectNotFound
	}
	return dup(d), nil
}

func (bm blockMemory) GetMany(ctx context.Context, ptrs []uint64) (map[uint64][]byte, error) {
	out := make(map[uint64][]byte)
	for _, ptr := range ptrs {
		val, ok := bm[ptr]
		if !ok {
			continue
		}
		out[ptr] = dup(val)
	}
	return out, nil
}

func (bm blockMemory) Set(ctx context.Context, ptr uint64, data []byte, _ DataType) error {
	bm[ptr] = dup(data)
	return nil
}

func (bm blockMemory) Commit(ctx context.Context) error { return nil }
func (bm blockMemory) Rollback(ctx context.Context)     {}

package persistent

import (
	"context"
	"errors"
)

type memory map[string][]byte

// NewMemory returns an object storage backend that simply stores data
// in-memory.
func NewMemory() ObjectStorage { return make(memory) }

func (m memory) Get(ctx context.Context, key string) ([]byte, error) {
	data, ok := m[key]
	if !ok {
		return nil, ErrObjectNotFound
	}
	return dup(data), nil
}

func (m memory) Set(ctx context.Context, key string, data []byte, dt DataType) error {
	m[key] = dup(data)
	return nil
}

func (m memory) Delete(ctx context.Context, key string) error {
	delete(m, key)
	return nil
}

type retry struct {
	base     ObjectStorage
	attempts int
}

// NewRetry wraps a base object storage backend, and will retry if requests
// fail.
func NewRetry(base ObjectStorage, attempts int) (ObjectStorage, error) {
	if attempts <= 0 {
		return nil, errors.New("storage: attempts must be greater than zero")
	}
	return &retry{base, attempts}, nil
}

func (r *retry) Get(ctx context.Context, key string) (data []byte, err error) {
	for i := 0; i < r.attempts; i++ {
		data, err = r.base.Get(ctx, key)
		if err == nil || err == ErrObjectNotFound {
			return
		}
	}

	return
}

func (r *retry) Set(ctx context.Context, key string, data []byte, dt DataType) (err error) {
	for i := 0; i < r.attempts; i++ {
		err = r.base.Set(ctx, key, data, dt)
		if err == nil {
			return
		}
	}

	return
}

func (r *retry) Delete(ctx context.Context, key string) (err error) {
	for i := 0; i < r.attempts; i++ {
		err = r.base.Delete(ctx, key)
		if err == nil {
			return
		}
	}

	return
}

type prefix struct {
	base   ObjectStorage
	prefix string
}

// NewPrefix wraps a base object storage backend, and ensures a user-provided
// prefix is added to all keys.
func NewPrefix(base ObjectStorage, p string) ObjectStorage {
	return &prefix{base, p}
}

func (p *prefix) Get(ctx context.Context, key string) ([]byte, error) {
	return p.base.Get(ctx, p.prefix+key)
}

func (p *prefix) Set(ctx context.Context, key string, data []byte, dt DataType) error {
	return p.base.Set(ctx, p.prefix+key, data, dt)
}

func (p *prefix) Delete(ctx context.Context, key string) error {
	return p.base.Delete(ctx, p.prefix+key)
}

package persistent

import (
	"context"
	"fmt"
)

// BufferedStorage is an extension of the ReliableStorage interface that will
// buffer many changes and then commit them all at once.
type BufferedStorage struct {
	base    ReliableStorage
	pending map[uint64]WriteData
}

func NewBufferedStorage(base ReliableStorage) BlockStorage {
	return &BufferedStorage{base: base}
}

func (bs *BufferedStorage) Start(ctx context.Context, prefetch []uint64) (map[uint64][]byte, error) {
	if bs.pending != nil {
		return nil, fmt.Errorf("app: transaction already started")
	}

	data, err := bs.base.Start(ctx, prefetch)
	if err != nil {
		return nil, err
	}
	bs.pending = make(map[uint64]WriteData)

	return data, nil
}

func (bs *BufferedStorage) Get(ctx context.Context, key uint64) ([]byte, error) {
	data, err := bs.GetMany(ctx, []uint64{key})
	if err != nil {
		return nil, err
	} else if data[key] == nil {
		return nil, ErrObjectNotFound
	}
	return data[key], nil
}

func (bs *BufferedStorage) GetMany(ctx context.Context, keys []uint64) (map[uint64][]byte, error) {
	if bs.pending == nil {
		return nil, fmt.Errorf("app: transaction not active")
	}

	out := make(map[uint64][]byte)
	remaining := make([]uint64, 0)
	for _, key := range keys {
		if wr, ok := bs.pending[key]; ok {
			if wr.Data != nil {
				out[key] = dup(wr.Data)
			}
			continue
		}
		remaining = append(remaining, key)
	}

	if len(remaining) > 0 {
		data, err := bs.base.GetMany(ctx, remaining)
		if err != nil {
			return nil, err
		}
		for key, val := range data {
			out[key] = val
		}
	}

	return out, nil
}

func (bs *BufferedStorage) Set(ctx context.Context, key uint64, data []byte, dt DataType) error {
	if bs.pending == nil {
		return fmt.Errorf("app: transaction not active")
	}
	bs.pending[key] = WriteData{Data: dup(data), Type: dt}
	return nil
}

func (bs *BufferedStorage) Delete(ctx context.Context, key uint64) error {
	if bs.pending == nil {
		return fmt.Errorf("app: transaction not active")
	}
	bs.pending[key] = WriteData{Data: nil}
	return nil
}

// Commit persists any changes made to the backend.
func (bs *BufferedStorage) Commit(ctx context.Context) error {
	if bs.pending == nil {
		return fmt.Errorf("app: transaction not active")
	}

	if err := bs.base.Commit(ctx, bs.pending); err != nil {
		return err
	}
	bs.pending = nil

	return nil
}

// Rollback discards all changes made in this transaction.
func (bs *BufferedStorage) Rollback(ctx context.Context) {
	bs.base.Commit(ctx, nil)
	bs.pending = nil
}

package persistent

import (
	"bytes"
	"context"

	"github.com/cloudflare/utahfs/cache"
)

type simpleReliable struct {
	base ObjectStorage
}

// NewSimpleReliable returns a ReliableStorage implementation, intended for
// testing. It simply panics if the atomicity of a transaction is broken.
func NewSimpleReliable(base ObjectStorage) ReliableStorage {
	return &simpleReliable{base}
}

func (sr *simpleReliable) Start(ctx context.Context, prefetch []uint64) (map[uint64][]byte, error) {
	return sr.GetMany(ctx, prefetch)
}

func (sr *simpleReliable) Get(ctx context.Context, key uint64) ([]byte, error) {
	return sr.base.Get(ctx, hex(key))
}

func (sr *simpleReliable) GetMany(ctx context.Context, keys []uint64) (map[uint64][]byte, error) {
	out := make(map[uint64][]byte)
	for _, key := range keys {
		val, err := sr.Get(ctx, key)
		if err == ErrObjectNotFound {
			continue
		} else if err != nil {
			return nil, err
		}
		out[key] = val
	}
	return out, nil
}

func (sr *simpleReliable) Commit(ctx context.Context, writes map[uint64]WriteData) error {
	for key, wr := range writes {
		if err := sr.base.Set(ctx, hex(key), wr.Data, wr.Type); err != nil {
			panic(err)
		}
	}
	return nil
}

type cacheStorage struct {
	base  ReliableStorage
	cache *cache.Cache
}

// NewCache wraps a base object storage backend with an LRU cache of the
// requested size.
func NewCache(base ReliableStorage, size int) ReliableStorage {
	return &cacheStorage{
		base:  base,
		cache: cache.New(cache.NoExpiration, 0, size),
	}
}

func (c *cacheStorage) filterCached(keys []uint64) (out map[uint64][]byte, remaining []uint64) {
	out = make(map[uint64][]byte)
	remaining = make([]uint64, 0)

	for _, key := range keys {
		val, ok := c.cache.Get(key)
		if ok {
			out[key] = dup(val.([]byte))
			continue
		}
		remaining = append(remaining, key)
	}

	return
}

func (c *cacheStorage) cacheAndOutput(data, out map[uint64][]byte) {
	for key, val := range data {
		out[key] = val
		c.cache.Set(key, dup(val), cache.NoExpiration)
	}
}

func (c *cacheStorage) Start(ctx context.Context, prefetch []uint64) (map[uint64][]byte, error) {
	out, remaining := c.filterCached(prefetch)

	data, err := c.base.Start(ctx, remaining)
	if err != nil {
		return nil, err
	}
	c.cacheAndOutput(data, out)

	return out, nil
}

func (c *cacheStorage) Get(ctx context.Context, key uint64) ([]byte, error) {
	data, err := c.GetMany(ctx, []uint64{key})
	if err != nil {
		return nil, err
	} else if data[key] == nil {
		return nil, ErrObjectNotFound
	}
	return data[key], nil
}

func (c *cacheStorage) GetMany(ctx context.Context, keys []uint64) (map[uint64][]byte, error) {
	out, remaining := c.filterCached(keys)

	if len(remaining) > 0 {
		data, err := c.base.GetMany(ctx, remaining)
		if err != nil {
			return nil, err
		}
		c.cacheAndOutput(data, out)
	}

	return out, nil
}

func (c *cacheStorage) skip(key uint64, data []byte) bool {
	cand, ok := c.cache.Get(key)
	return ok && bytes.Equal(cand.([]byte), data)
}

func (c *cacheStorage) Commit(ctx context.Context, writes map[uint64]WriteData) error {
	dedupedWrites := make(map[uint64]WriteData)
	for key, wr := range writes {
		if c.skip(key, wr.Data) {
			continue
		}
		dedupedWrites[key] = wr
	}

	if err := c.base.Commit(ctx, dedupedWrites); err != nil {
		return err
	}

	for key, wr := range dedupedWrites {
		if wr.Data == nil {
			c.cache.Delete(key)
		} else {
			c.cache.Set(key, dup(wr.Data), cache.NoExpiration)
		}
	}
	return nil
}

type blockReliable struct {
	BlockStorage
}

// NewBlockReliable returns a ReliableStorage implementation based on a
// BlockStorage implementation.
func NewBlockReliable(base BlockStorage) ReliableStorage {
	return &blockReliable{base}
}

func (br *blockReliable) Commit(ctx context.Context, writes map[uint64]WriteData) error {
	for ptr, wd := range writes {
		if err := br.Set(ctx, ptr, wd.Data, wd.Type); err != nil {
			return err
		}
	}
	return br.BlockStorage.Commit(ctx)
}

package persistent

import (
	"testing"

	"bytes"
	"context"
	"crypto/rand"
	"io/ioutil"
	mrand "math/rand"
	"os"
	"time"
)

func init() {
	mrand.Seed(time.Now().UnixNano())
}

func TestOblivious(t *testing.T) {
	// Choose a temp directory for the databases and pin file.
	tempDir, err := ioutil.TempDir("", "")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(tempDir)

	// Setup client-side ORAM storage.
	localStore, err := NewLocalOblivious(tempDir + "/oram")
	if err != nil {
		t.Fatal(err)
	}

	// Setup block storage.
	disk, err := NewDisk(tempDir + "/db")
	if err != nil {
		t.Fatal(err)
	}
	base := NewBufferedStorage(NewSimpleReliable(disk))

	integ, err := WithIntegrity(base, "password", tempDir+"/pin.json")
	if err != nil {
		t.Fatal(err)
	}
	enc := WithEncryption(integ, "password")
	auditor := &oramAuditor{base: enc}

	store, err := WithORAM(auditor, localStore, 16)
	if err != nil {
		t.Fatal(err)
	}

	// Run tests.
	t.Run("Correctness", testORAMCorrectness(store))
	t.Run("Randomness", testORAMRandomness(auditor, store))
}

// testORAMCorrectness checks that data stored in ORAM can be successfully
// fetched later, provided that it hasn't been rolled back.
func testORAMCorrectness(store BlockStorage) func(t *testing.T) {
	return func(t *testing.T) {
		ctx := context.Background()
		backup := NewBlockMemory()

		for i := 0; i < 50; i++ {
			// Start a transaction.
			if _, err := store.Start(ctx, nil); err != nil {
				t.Fatal(err)
			}
			rollback := mrand.Intn(3) == 2
			dirty := mrand.Intn(3) == 2

			// Make a series of random writes to store that may or may not be
			// rolled back.
			for i := 0; i < 10; i++ {
				ptr := uint64(mrand.Intn(100))
				val := make([]byte, mrand.Intn(15)+1)
				if _, err := rand.Read(val); err != nil {
					t.Fatal(err)
				}

				if err := store.Set(ctx, ptr, dup(val), Content); err != nil {
					t.Fatal(err)
				}
				if !rollback {
					backup.Set(ctx, ptr, val, Content)
				}
			}

			// Rollback if needed.
			if rollback {
				if dirty {
					store.(*oblivious).dirtyRollback(ctx)
				} else {
					store.Rollback(ctx)
				}
				continue
			}

			// Do a series of random reads and check for consistency.
			for i := 0; i < 10; i++ {
				ptr := uint64(mrand.Intn(100))

				val1, err1 := store.Get(ctx, ptr)
				val2, err2 := backup.Get(ctx, ptr)

				if err1 == ErrObjectNotFound && err2 == ErrObjectNotFound {
					continue
				} else if err1 != nil {
					t.Fatal(err1)
				} else if !bytes.Equal(val1, val2) {
					t.Fatal("ORAM storage contains a different value than backup!")
				}
			}

			// Commit changes.
			if err := store.Commit(ctx); err != nil {
				t.Fatal(err)
			}
		}
	}
}

func testORAMRandomness(auditor *oramAuditor, store BlockStorage) func(t *testing.T) {
	return func(t *testing.T) {
		ctx := context.Background()

		// Ensure the number of blocks is a power of two.
		if _, err := store.Start(ctx, nil); err != nil {
			t.Fatal(err)
		}
		for ptr := uint64(0); ptr < 256; ptr++ {
			if err := store.Set(ctx, ptr, make([]byte, 16), Content); err != nil {
				t.Fatal(err)
			}
		}
		if err := store.Commit(ctx); err != nil {
			t.Fatal(err)
		}

		// Make the same read several times and keep track of how often each
		// node is accessed.
		const n = 100
		totalAccesses := make(map[uint64]int)

		for i := 0; i < n; i++ {
			if _, err := store.Start(ctx, nil); err != nil {
				t.Fatal(err)
			} else if _, err := store.Get(ctx, 0); err != nil {
				t.Fatal(err)
			} else if err := store.Commit(ctx); err != nil {
				t.Fatal(err)
			}

			for node, count := range auditor.blocksRead {
				totalAccesses[node] += count
			}
		}

		// Check that the number of times each node was accessed is proportional
		// to its level in the tree.
		levels := make(map[uint64][]int)
		for i := uint64(0); i < 9; i++ {
			levels[i] = make([]int, 1<<(8-i))
		}
		for node := uint64(0); node < treeWidth(256); node++ {
			l := level(node)

			offset := (uint64(1) << l) - 1
			scale := 2*offset + 2

			levelId := (node - offset) / scale

			levels[l][levelId] += totalAccesses[node]
		}

		for i := uint64(0); i < 9; i++ {
			t.Logf("Level %v: %v", i, levels[i])

			if i > 4 {
				for _, count := range levels[i] {
					if count == 0 {
						t.Fatal("ORAM accesses aren't sufficiently distributed across the tree")
					}
				}
			}
		}
	}
}

package persistent

import (
	"bytes"
	"context"
	"encoding/gob"
	"fmt"

	"github.com/prometheus/client_golang/prometheus"
)

var AppStorageCommits = prometheus.NewCounter(prometheus.CounterOpts{
	Name: "app_storage_commits",
	Help: "The number of successful app storage transactions committed.",
})

// State contains all of the shared global state of a deployment.
type State struct {
	// RootPtr points to the root inode of the filesystem.
	RootPtr uint64

	// Blocks that were previously allocated but are now un-used are kept in a
	// linked list. TrashPtr points to the head of this list.
	TrashPtr uint64
	// NextPtr will be the pointer of the next block which is allocated.
	NextPtr uint64
}

func NewState() *State {
	return &State{
		RootPtr: nilPtr,

		TrashPtr: nilPtr,
		NextPtr:  0,
	}
}

func (s *State) Clone() *State {
	return &State{
		RootPtr: s.RootPtr,

		TrashPtr: s.TrashPtr,
		NextPtr:  s.NextPtr,
	}
}

// AppStorage is an extension of the BlockStorage interface that provides shared
// state.
type AppStorage struct {
	base BlockStorage

	active          bool
	original, state *State
}

func NewAppStorage(base BlockStorage) *AppStorage {
	return &AppStorage{base: base}
}

func (as *AppStorage) Start(ctx context.Context) error {
	if as.active {
		return fmt.Errorf("app: transaction already started")
	}

	if _, err := as.base.Start(ctx, nil); err != nil {
		return err
	}
	as.active = true

	return nil
}

// State returns a struct of shared global state. Consumers may modify the
// returned struct, and these modifications will be persisted after Commit is
// called.
func (as *AppStorage) State(ctx context.Context) (*State, error) {
	if !as.active {
		return nil, fmt.Errorf("app: transaction not active")
	} else if as.state != nil {
		return as.state, nil
	}

	raw, err := as.base.Get(ctx, 0)
	if err == ErrObjectNotFound {
		as.original, as.state = NewState(), NewState()
	} else if err != nil {
		return nil, err
	} else {
		state := &State{}
		if err := gob.NewDecoder(bytes.NewBuffer(raw)).Decode(state); err != nil {
			return nil, err
		}
		as.original, as.state = state, state.Clone()
	}

	return as.state, nil
}

func (as *AppStorage) Get(ctx context.Context, ptr uint64) ([]byte, error) {
	if !as.active {
		return nil, fmt.Errorf("app: transaction not active")
	}
	return as.base.Get(ctx, ptr+1)
}

func (as *AppStorage) GetMany(ctx context.Context, ptrs []uint64) (map[uint64][]byte, error) {
	if !as.active {
		return nil, fmt.Errorf("app: transaction not active")
	}

	corrected := make([]uint64, 0, len(ptrs))
	for _, ptr := range ptrs {
		corrected = append(corrected, ptr+1)
	}

	data, err := as.base.GetMany(ctx, corrected)
	if err != nil {
		return nil, err
	}

	out := make(map[uint64][]byte)
	for ptr, val := range data {
		out[ptr-1] = val
	}
	return out, nil
}

func (as *AppStorage) Set(ctx context.Context, ptr uint64, data []byte, dt DataType) error {
	if !as.active {
		return fmt.Errorf("app: transaction not active")
	}
	return as.base.Set(ctx, ptr+1, data, dt)
}

func (as *AppStorage) Commit(ctx context.Context) error {
	if !as.active {
		return fmt.Errorf("app: transaction not active")
	}

	if as.original != nil && *as.original != *as.state {
		buff := &bytes.Buffer{}
		if err := gob.NewEncoder(buff).Encode(as.state); err != nil {
			return err
		} else if err := as.base.Set(ctx, 0, buff.Bytes(), Metadata); err != nil {
			return err
		}
	}
	if err := as.base.Commit(ctx); err != nil {
		return err
	}
	as.active = false
	as.original, as.state = nil, nil

	AppStorageCommits.Inc()
	return nil
}

func (as *AppStorage) Rollback(ctx context.Context) {
	as.base.Rollback(ctx)
	as.active = false
	as.original, as.state = nil, nil
}

