package persistent

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"os"
	"path"
	"strings"

	_ "github.com/mattn/go-sqlite3"
)

type obliviousStore struct {
	base ObliviousStorage

	Stash map[uint64][]byte
	Count uint64

	assignments map[uint64]uint64
}

// newObliviousStore wraps an implementation of the simpler ObliviousStorage
// interface and makes it a bit more user-friendly.
func newObliviousStore(base ObliviousStorage) *obliviousStore {
	return &obliviousStore{base: base}
}

func (os *obliviousStore) Start(ctx context.Context, version uint64) error {
	stash, count, err := os.base.Start(ctx, version)
	if err != nil {
		return err
	}

	os.Stash = stash
	os.Count = count
	os.assignments = make(map[uint64]uint64)

	return nil
}

func (os *obliviousStore) Lookup(ctx context.Context, ptrs []uint64) (map[uint64]uint64, error) {
	out := make(map[uint64]uint64)

	// Get as many pointers as possible from the local `assignments` field.
	remaining := make([]uint64, 0)
	for _, ptr := range ptrs {
		if leaf, ok := os.assignments[ptr]; ok {
			out[ptr] = leaf
		} else {
			remaining = append(remaining, ptr)
		}
	}
	if len(remaining) == 0 {
		return out, nil
	}

	// Fetch the remaining from the base implementation.
	part, err := os.base.Lookup(ctx, remaining)
	if err != nil {
		return nil, err
	}
	for ptr, leaf := range part {
		out[ptr] = leaf
	}

	return out, nil
}

func (os *obliviousStore) Assign(assignments map[uint64]uint64) {
	for ptr, leaf := range assignments {
		os.assignments[ptr] = leaf
	}
}

func (os *obliviousStore) Commit(ctx context.Context, version uint64) error {
	err := os.base.Commit(ctx, version, os.Stash, os.assignments)

	os.Stash = nil
	os.Count = 0
	os.assignments = nil

	return err
}

func (os *obliviousStore) Rollback(ctx context.Context) {
	os.base.Rollback(ctx)

	os.Stash = nil
	os.Count = 0
	os.assignments = nil
}

type localOblivious struct {
	db *sql.DB

	tx      *sql.Tx
	version uint64
}

// NewLocalOblivious returns an implementation of the ObliviousStorage
// interface, used for storing temporary ORAM data, that's backed by an on-disk
// database at `loc`.
func NewLocalOblivious(loc string) (ObliviousStorage, error) {
	if err := os.MkdirAll(path.Dir(loc), 0744); err != nil {
		return nil, err
	}
	db, err := sql.Open("sqlite3", loc)
	if err != nil {
		return nil, err
	}
	_, err = db.Exec("CREATE TABLE IF NOT EXISTS stash (ptr integer, val bytea, version integer, UNIQUE(ptr, version))")
	if err != nil {
		return nil, err
	}
	_, err = db.Exec("CREATE TABLE IF NOT EXISTS position (ptr integer, leaf integer, version integer, UNIQUE(ptr, version))")
	if err != nil {
		return nil, err
	}
	_, err = db.Exec("CREATE TABLE IF NOT EXISTS assignments (version integer not null primary key, data bytea)")
	if err != nil {
		return nil, err
	}

	return &localOblivious{db: db}, nil
}

func (lo *localOblivious) Start(ctx context.Context, version uint64) (map[uint64][]byte, uint64, error) {
	tx, err := lo.db.BeginTx(context.Background(), nil)
	if err != nil {
		return nil, 0, err
	}

	stash, count, err := lo.initTx(ctx, version, tx)
	if err != nil {
		tx.Rollback()
		return nil, 0, err
	}

	lo.tx = tx
	lo.version = version
	return stash, count, nil
}

func (lo *localOblivious) initTx(ctx context.Context, version uint64, tx *sql.Tx) (map[uint64][]byte, uint64, error) {
	// Read the stash into memory.
	stash := make(map[uint64][]byte)

	rows, err := tx.QueryContext(ctx, "SELECT ptr, val FROM stash WHERE version = ?", version)
	if err != nil {
		return nil, 0, err
	}
	for rows.Next() {
		var (
			ptr uint64
			val []byte
		)
		if err := rows.Scan(&ptr, &val); err != nil {
			rows.Close()
			return nil, 0, err
		}
		stash[ptr] = val
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return nil, 0, err
	}
	rows.Close()

	// Keep the stash clean by deleting entries that don't correspond to the
	// current version.
	_, err = tx.ExecContext(ctx, "DELETE FROM stash WHERE version != ?", version)
	if err != nil {
		return nil, 0, err
	}

	// Compute the count of leaves stored.
	var count *uint64
	err = tx.QueryRowContext(ctx, "SELECT MAX(ptr) FROM position WHERE version <= ?", version).Scan(&count)
	if err != nil {
		return nil, 0, err
	} else if count == nil {
		count = new(uint64)
	} else {
		*count += 1
	}

	// Keep the positions map clean by removing overlapping assignments and
	// removing future, failed versions.
	if err := lo.deleteOverlapping(ctx, version, tx); err != nil {
		return nil, 0, err
	}
	_, err = tx.ExecContext(ctx, "DELETE FROM position WHERE version > ?", version)
	if err != nil {
		return nil, 0, err
	}
	_, err = tx.ExecContext(ctx, "DELETE FROM assignments")
	if err != nil {
		return nil, 0, err
	}

	return stash, *count, nil
}

// deleteOverlapping deletes previous versions of assignments that were made
// while the current version was being created. That is, it makes sure there are
// no more rows with the same `ptr` value.
func (lo *localOblivious) deleteOverlapping(ctx context.Context, version uint64, tx *sql.Tx) error {
	var data []byte
	err := tx.QueryRowContext(ctx, "SELECT data FROM assignments WHERE version = ?", version).Scan(&data)
	if err == sql.ErrNoRows {
		return nil
	} else if err != nil {
		return err
	}

	var ptrs []uint64
	if err := json.Unmarshal(data, &ptrs); err != nil {
		return err
	}
	ptrStrs := make([]string, 0, len(ptrs))
	for _, ptr := range ptrs {
		ptrStrs = append(ptrStrs, fmt.Sprint(ptr))
	}
	_, err = tx.ExecContext(ctx, "DELETE FROM position WHERE ptr IN ("+strings.Join(ptrStrs, ",")+") AND version != ?", version)
	if err != nil {
		return err
	}

	return nil
}

func (lo *localOblivious) Lookup(ctx context.Context, ptrs []uint64) (map[uint64]uint64, error) {
	ptrStrs := make([]string, 0, len(ptrs))
	for _, ptr := range ptrs {
		ptrStrs = append(ptrStrs, fmt.Sprint(ptr))
	}
	out := make(map[uint64]uint64)

	rows, err := lo.tx.QueryContext(ctx, "SELECT ptr, leaf FROM position WHERE ptr IN ("+strings.Join(ptrStrs, ",")+")")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var ptr, leaf uint64
		if err := rows.Scan(&ptr, &leaf); err != nil {
			rows.Close()
			return nil, err
		} else if _, ok := out[ptr]; ok {
			return nil, fmt.Errorf("oblivious: same pointer present multiple times in query results")
		}
		out[ptr] = leaf
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return nil, err
	}
	rows.Close()

	return out, nil
}

func (lo *localOblivious) Commit(ctx context.Context, version uint64, stash map[uint64][]byte, assignments map[uint64]uint64) error {
	if version < lo.version {
		return fmt.Errorf("oblivious: cannot commit at lower version number than before")
	} else if version == lo.version {
		lo.Rollback(ctx)
		return nil
	}

	for ptr, val := range stash {
		_, err := lo.tx.ExecContext(ctx, "INSERT INTO stash (ptr, val, version) VALUES (?, ?, ?)", ptr, val, version)
		if err != nil {
			return err
		}
	}

	for ptr, leaf := range assignments {
		_, err := lo.tx.ExecContext(ctx, "INSERT INTO position (ptr, leaf, version) VALUES (?, ?, ?)", ptr, leaf, version)
		if err != nil {
			return err
		}
	}

	ptrs := make([]uint64, 0, len(assignments))
	for ptr, _ := range assignments {
		ptrs = append(ptrs, ptr)
	}
	data, err := json.Marshal(ptrs)
	if err != nil {
		return err
	}
	_, err = lo.tx.ExecContext(ctx, "INSERT INTO assignments (version, data) VALUES (?, ?)", version, data)
	if err != nil {
		return err
	}

	if err := lo.tx.Commit(); err != nil {
		return err
	}
	lo.tx = nil
	lo.version = 0
	return nil
}

func (lo *localOblivious) Rollback(ctx context.Context) {
	if lo.tx == nil {
		return
	}
	lo.tx.Rollback()
	lo.tx = nil
	lo.version = 0
}

// Package cache implements a capped-size in-memory cache that randomly evicts
// elements when it reaches max size.
package cache

import (
	"crypto/rand"
	"runtime"
	"sync"
	"time"
)

type Item struct {
	Object     interface{}
	Expiration int64
}

// Returns true if the item has expired.
func (item Item) Expired() bool {
	if item.Expiration == 0 {
		return false
	}
	return time.Now().UnixNano() > item.Expiration
}

const (
	// For use with functions that take an expiration time.
	NoExpiration time.Duration = -1
	// For use with functions that take an expiration time. Equivalent to
	// passing in the same expiration duration as was given to New() or
	// NewFrom() when the cache was created (e.g. 5 minutes.)
	DefaultExpiration time.Duration = 0
)

type Cache struct {
	*cache
	// If this is confusing, see the comment at the bottom of New()
}

type cache struct {
	defaultExpiration time.Duration
	items             map[interface{}]Item
	keys              *keyList
	mu                sync.RWMutex
	janitor           *janitor
}

// Add an item to the cache, replacing any existing item. If the duration is 0
// (DefaultExpiration), the cache's default expiration time is used. If it is -1
// (NoExpiration), the item never expires.
func (c *cache) Set(k, x interface{}, d time.Duration) {
	var e int64
	if d == DefaultExpiration {
		d = c.defaultExpiration
	}
	if d > 0 {
		e = time.Now().Add(d).UnixNano()
	}
	c.mu.Lock()
	if _, ok := c.items[k]; !ok {
		evicted, ok := c.keys.insert(k)
		if ok {
			delete(c.items, evicted)
		}
	}
	c.items[k] = Item{
		Object:     x,
		Expiration: e,
	}
	c.mu.Unlock()
}

// Get an item from the cache. Returns the item or nil, and a bool indicating
// whether the key was found.
func (c *cache) Get(k interface{}) (interface{}, bool) {
	c.mu.RLock()
	item, found := c.items[k]
	c.mu.RUnlock()
	if !found {
		return nil, false
	} else if item.Expired() {
		return nil, false
	}
	return item.Object, true
}

// Delete the specified key from the cache.
func (c *cache) Delete(k interface{}) {
	c.mu.Lock()
	for i := 0; i < len(c.keys.keys); i++ {
		if c.keys.keys[i] == k {
			c.keys.evictAt(i)
			break
		}
	}
	delete(c.items, k)
	c.mu.Unlock()
}

// Delete all expired items from the cache.
func (c *cache) DeleteExpired() {
	c.mu.Lock()
	for i := 0; i < len(c.keys.keys); i++ {
		k := c.keys.keys[i]
		v, ok := c.items[k]
		if !ok {
			panic("cache inconsistent")
		}
		if v.Expired() {
			c.keys.evictAt(i)
			delete(c.items, k)
		}
	}
	c.mu.Unlock()
}

type janitor struct {
	Interval time.Duration
	stop     chan bool
}

func (j *janitor) Run(c *cache) {
	ticker := time.NewTicker(j.Interval)
	for {
		select {
		case <-ticker.C:
			c.DeleteExpired()
		case <-j.stop:
			ticker.Stop()
			return
		}
	}
}

func stopJanitor(c *Cache) {
	c.janitor.stop <- true
}

func runJanitor(c *cache, ci time.Duration) {
	j := &janitor{
		Interval: ci,
		stop:     make(chan bool),
	}
	c.janitor = j
	go j.Run(c)
}

func newCache(de time.Duration, maxSize int, m map[interface{}]Item) *cache {
	if de == 0 {
		de = -1
	}
	c := &cache{
		defaultExpiration: de,
		items:             m,
		keys:              &keyList{maxSize: maxSize},
	}
	return c
}

func newCacheWithJanitor(de time.Duration, ci time.Duration, maxSize int, m map[interface{}]Item) *Cache {
	c := newCache(de, maxSize, m)
	// This trick ensures that the janitor goroutine (which--granted it
	// was enabled--is running DeleteExpired on c forever) does not keep
	// the returned C object from being garbage collected. When it is
	// garbage collected, the finalizer stops the janitor goroutine, after
	// which c can be collected.
	C := &Cache{c}
	if ci > 0 {
		runJanitor(c, ci)
		runtime.SetFinalizer(C, stopJanitor)
	}
	return C
}

// New returns a new cache with a given default expiration duration and cleanup
// interval. If the expiration duration is less than one (or NoExpiration), the
// items in the cache never expire (by default), and must be deleted manually.
// If the cleanup interval is less than one, expired items are not deleted from
// the cache before calling c.DeleteExpired().
func New(defaultExpiration, cleanupInterval time.Duration, maxSize int) *Cache {
	items := make(map[interface{}]Item)
	return newCacheWithJanitor(defaultExpiration, cleanupInterval, maxSize, items)
}

// keyList stores the list of keys in our cache in a way that is easy to
// randomly sample.
type keyList struct {
	keys    []interface{}
	maxSize int
}

func (kl *keyList) insert(key interface{}) (interface{}, bool) {
	if len(kl.keys) < kl.maxSize {
		kl.keys = append(kl.keys, key)
		return "", false
	}

	// Randomly sample an index in keys.
	buff := make([]byte, 8)
	if _, err := rand.Read(buff); err != nil {
		panic(err)
	}
	var i int
	for _, b := range buff {
		i = (i << 8) | int(b)
	}
	if i < 0 {
		i = -i
	}
	i = i % len(kl.keys)

	// Replace the key at position i with the new one, return what was there.
	old := kl.keys[i]
	kl.keys[i] = key
	return old, true
}

func (kl *keyList) evictAt(i int) {
	n := len(kl.keys)

	kl.keys[i], kl.keys[n-1] = kl.keys[n-1], kl.keys[i]
	kl.keys = kl.keys[:n-1]
}

package persistent

import (
	"context"
)

type tieredCache struct {
	special DataType

	high, base ObjectStorage
}

// NewTieredCache returns a cache-like object storage implementation, where
// objects matching the `special` data type are stored in both `high` and
// `base`, while all other objects are stored only in `base`.
func NewTieredCache(special DataType, high, base ObjectStorage) ObjectStorage {
	return &tieredCache{
		special: special,

		high: high,
		base: base,
	}
}

func (tc *tieredCache) Get(ctx context.Context, key string) ([]byte, error) {
	data, err := tc.high.Get(ctx, key)
	if err == ErrObjectNotFound {
		return tc.base.Get(ctx, key)
	} else if err != nil {
		return nil, err
	}
	return data, nil
}

func (tc *tieredCache) Set(ctx context.Context, key string, data []byte, dt DataType) error {
	if dt == tc.special {
		if err := tc.high.Set(ctx, key, data, dt); err != nil {
			return err
		}
	}
	return tc.base.Set(ctx, key, data, dt)
}

func (tc *tieredCache) Delete(ctx context.Context, key string) error {
	if err := tc.high.Delete(ctx, key); err != nil {
		return err
	}
	return tc.base.Delete(ctx, key)
}

package persistent

import (
	"context"
	"database/sql"
	"log"
	"math/rand"
	"os"
	"path"
	"sync"

	_ "github.com/mattn/go-sqlite3"

	"github.com/prometheus/client_golang/prometheus"
)

var DiskCacheSize = prometheus.NewGaugeVec(
	prometheus.GaugeOpts{
		Name: "disk_cache_size",
		Help: "The number of entries in the on-disk cache.",
	},
	[]string{"path"},
)

type diskCache struct {
	mu    sync.Mutex
	mapMu MapMutex

	base    ObjectStorage
	loc     string
	size    int64
	exclude []DataType

	n  int64
	db *sql.DB
}

// NewDiskCache wraps a base object storage backend with a large on-disk cache
// stored at `loc`.
func NewDiskCache(base ObjectStorage, loc string, size int64, exclude []DataType) (ObjectStorage, error) {
	if err := os.MkdirAll(path.Dir(loc), 0744); err != nil {
		return nil, err
	}
	db, err := sql.Open("sqlite3", loc)
	if err != nil {
		return nil, err
	}
	_, err = db.Exec("CREATE TABLE IF NOT EXISTS cache (key text not null primary key, val bytea)")
	if err != nil {
		return nil, err
	}

	// Get the max rowid in the cache.
	var n *int64
	err = db.QueryRow("SELECT MAX(rowid) FROM cache").Scan(&n)
	if err != nil {
		return nil, err
	} else if n == nil {
		n = new(int64)
	}

	DiskCacheSize.WithLabelValues(loc).Set(float64(*n))
	return &diskCache{
		mapMu: NewMapMutex(),

		base:    base,
		loc:     loc,
		size:    size,
		exclude: exclude,

		n:  *n,
		db: db,
	}, nil
}

func (dc *diskCache) addToCache(ctx context.Context, key string, data []byte) {
	dc.mu.Lock()
	defer dc.mu.Unlock()

	tx, err := dc.db.BeginTx(ctx, nil)
	if err != nil {
		log.Println(err)
		return
	}
	defer tx.Rollback()

	n := dc.n + 1
	i := rand.Int63n(n) + 1

	// Move a random existing entry into the next rowid slot.
	if i != dc.n {
		_, err := tx.ExecContext(ctx, "UPDATE cache SET rowid = ? WHERE rowid = ?", n, i)
		if err != nil {
			log.Println(err)
			return
		}
	}
	// Add the new row to the cache.
	_, err = tx.ExecContext(ctx, "INSERT OR REPLACE INTO cache (rowid, key, val) VALUES (?, ?, ?)", i, key, data)
	if err != nil {
		log.Println(err)
		return
	}
	// Evict from the cache until we're back at/below the target size.
	for n > dc.size {
		if _, err := tx.ExecContext(ctx, "DELETE FROM cache WHERE rowid = ?", n); err != nil {
			log.Println(err)
			return
		}
		n -= 1
	}

	// Commit the transaction.
	if err := tx.Commit(); err != nil {
		log.Println(err)
		return
	}
	dc.n = n
	DiskCacheSize.WithLabelValues(dc.loc).Set(float64(n))
}

func (dc *diskCache) removeFromCache(ctx context.Context, key string) {
	dc.mu.Lock()
	defer dc.mu.Unlock()

	tx, err := dc.db.BeginTx(ctx, nil)
	if err != nil {
		log.Println(err)
		return
	}
	defer tx.Rollback()

	// Get the rowid of the key we want to delete.
	var rowid int64
	err = tx.QueryRowContext(ctx, "SELECT rowid FROM cache WHERE key = ?", key).Scan(&rowid)
	if err == sql.ErrNoRows {
		return
	} else if err != nil {
		log.Println(err)
		return
	}
	// Delete the row.
	if _, err := tx.ExecContext(ctx, "DELETE FROM cache WHERE rowid = ?", rowid); err != nil {
		log.Println(err)
		return
	}
	// Move something into this rowid gap.
	if _, err := tx.ExecContext(ctx, "UPDATE cache SET rowid = ? WHERE rowid = ?", rowid, dc.n); err != nil {
		log.Println(err)
		return
	}

	// Commit the transaction.
	if err := tx.Commit(); err != nil {
		log.Println(err)
		return
	}
	dc.n -= 1
	DiskCacheSize.WithLabelValues(dc.loc).Set(float64(dc.n))
}

func (dc *diskCache) Get(ctx context.Context, key string) ([]byte, error) {
	dc.mapMu.Lock(key)
	defer dc.mapMu.Unlock(key)

	var data []byte
	dc.mu.Lock()
	err := dc.db.QueryRowContext(ctx, "SELECT val FROM cache WHERE key = ?", key).Scan(&data)
	dc.mu.Unlock()
	if err == sql.ErrNoRows {
		data, err = dc.base.Get(ctx, key)
		if err != nil {
			return nil, err
		}
		dc.addToCache(ctx, key, data)
		return data, nil
	} else if err != nil {
		return nil, err
	}
	return data, nil
}

func (dc *diskCache) Set(ctx context.Context, key string, data []byte, dt DataType) error {
	dc.mapMu.Lock(key)
	defer dc.mapMu.Unlock(key)

	if err := dc.base.Set(ctx, key, data, dt); err != nil {
		dc.removeFromCache(ctx, key)
		return err
	}

	// Check if this key has an excluded data type and skip caching if so.
	for _, cand := range dc.exclude {
		if dt == cand {
			return nil
		}
	}
	// Type isn't excluded; good to cache.
	dc.addToCache(ctx, key, data)
	return nil
}

func (dc *diskCache) Delete(ctx context.Context, key string) error {
	dc.mapMu.Lock(key)
	defer dc.mapMu.Unlock(key)

	err := dc.base.Delete(ctx, key)
	dc.removeFromCache(ctx, key)
	return err
}
